"""Frozen operator acceptance for opt-in strict chunking; outside candidate."""
import pytest
from boltons.iterutils import chunked, chunked_iter


@pytest.mark.parametrize('source,expected', [([], []), ([1,2,3,4], [[1,2],[3,4]]),
                                           ('abcd', ['ab','cd']), (b'abcd', [b'ab',b'cd'])])
def test_strict_exact_and_empty(source, expected):
    assert list(chunked_iter(source, 2, strict=True)) == expected
    assert chunked(source, 2, strict=True) == expected


@pytest.mark.parametrize('source', [[1,2,3], 'abc', b'abc'])
def test_strict_partial_raises(source):
    with pytest.raises(ValueError, match='incomplete chunk'):
        list(chunked_iter(source, 2, strict=True))
    with pytest.raises(ValueError, match='incomplete chunk'):
        chunked(source, 2, strict=True)


def test_iterator_validates_lazily_and_preserves_complete_prefix():
    consumed = []
    def source():
        for i in range(5):
            consumed.append(i)
            yield i
    result = chunked_iter(source(), 2, strict=True)
    assert consumed == []
    assert next(result) == [0,1]
    assert consumed == [0,1]
    assert next(result) == [2,3]
    assert consumed == [0,1,2,3]
    with pytest.raises(ValueError, match='incomplete chunk'):
        next(result)
    assert consumed == [0,1,2,3,4]


@pytest.mark.parametrize('fill', [None, 0])
def test_strict_and_explicit_fill_are_incompatible(fill):
    with pytest.raises(ValueError, match='strict.*fill'):
        list(chunked_iter([1,2], 2, strict=True, fill=fill))


def test_default_false_and_fill_behavior_are_unchanged():
    assert chunked([1,2,3], 2) == [[1,2],[3]]
    assert chunked([1,2,3], 2, strict=False) == [[1,2],[3]]
    assert chunked([1,2,3], 2, strict=False, fill=None) == [[1,2],[3,None]]


def test_count_limited_wrapper_does_not_consume_unrequested_tail():
    assert chunked([1,2,3], 2, count=1, strict=True) == [[1,2]]


@pytest.mark.parametrize('size', [0, -1])
def test_original_size_validation_remains(size):
    with pytest.raises(ValueError):
        list(chunked_iter([1], size, strict=True))

