#include <rigtorp/SPSCQueue.h>
#include <atomic>
#include <cstdint>
#include <cstdlib>
#include <memory>
#include <string>
#include <thread>

void require(bool condition) { if (!condition) std::abort(); }

void stress() {
  constexpr std::uint64_t count = 50000;
  for (std::size_t capacity : {1, 2, 7, 64}) {
    rigtorp::SPSCQueue<std::uint64_t> queue(capacity);
    std::atomic<bool> start{false};
    std::thread producer([&] {
      while (!start.load(std::memory_order_acquire)) std::this_thread::yield();
      for (std::uint64_t i = 0; i < count; ++i) {
#ifdef MUTATE_FIFO
        auto value = i == 10 ? 9 : i;
#else
        auto value = i;
#endif
        while (!queue.try_push(value)) std::this_thread::yield();
      }
    });
    std::thread consumer([&] {
      start.store(true, std::memory_order_release);
      for (std::uint64_t i = 0; i < count; ++i) {
        const std::uint64_t *value;
        while (!(value = queue.front())) std::this_thread::yield();
        require(*value == i);
        queue.pop();
      }
    });
    producer.join(); consumer.join();
    require(queue.front() == nullptr);
  }
}

struct Item {
  static std::atomic<int> live;
  int id;
  explicit Item(int n) : id(n) { ++live; }
  ~Item() { --live; }
};
std::atomic<int> Item::live{0};

void lifetime() {
  {
    rigtorp::SPSCQueue<std::unique_ptr<Item>> queue(7);
    for (int i = 0; i < 7; ++i) require(queue.try_push(std::make_unique<Item>(i)));
    require(Item::live == 7);
    for (int i = 0; i < 3; ++i) {
      require(queue.front() && (*queue.front())->id == i);
      queue.pop();
    }
    require(Item::live == 4);
    // Leave live move-only objects queued: queue destruction must release them.
  }
  require(Item::live == 0);
}

int main(int argc, char **argv) {
  if (argc != 2) return 2;
  if (std::string(argv[1]) == "stress") stress();
  else if (std::string(argv[1]) == "lifetime") lifetime();
  else return 2;
}

